originalCss:
:root {
    --bg: #07111e;
    --bg2: #0b1a2c;
    --card: #0f2036;
    --card2: #132a45;
    --line: #1f3555;
    --text: #e6edf7;
    --muted: #9db0cc;
    --accent: #7c9eff;
    --green: #56d6a0;
    --amber: #e2b45a;
    --rose: #ff8a9b;
    --violet: #b49cff;
    --sans:
        'Noto Sans JP', system-ui, -apple-system, 'Hiragino Sans', 'Yu Gothic',
        sans-serif;
    --mono: 'JetBrains Mono', ui-monospace, Menlo, monospace;
}
* {
    box-sizing: border-box;
}
html {
    scroll-behavior: smooth;
    scroll-padding-top: 20px;
}
body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font-family: var(--sans);
    font-size: 16px;
    line-height: 1.9;
    -webkit-text-size-adjust: 100%;
}
a {
    color: var(--accent);
    text-decoration: none;
    word-break: break-all;
}
a:hover {
    text-decoration: underline;
}
.sidebar {
    position: fixed;
    inset: 0 auto 0 0;
    width: 300px;
    overflow-y: auto;
    background: var(--bg2);
    border-right: 1px solid var(--line);
    padding: 22px 14px 40px;
    z-index: 30;
}
.side-title {
    font-family: var(--mono);
    font-size: 12px;
    letter-spacing: 0.06em;
    color: var(--accent);
    padding: 0 10px 14px;
    border-bottom: 1px solid var(--line);
    margin-bottom: 10px;
}
.sidebar a {
    display: block;
    color: var(--muted);
    font-size: 13px;
    line-height: 1.5;
    padding: 7px 10px;
    border-radius: 8px;
    word-break: normal;
}
.sidebar a.nav-h3 {
    padding-left: 24px;
    font-size: 12px;
}
.sidebar a:hover {
    background: var(--card);
    color: var(--text);
    text-decoration: none;
}
.sidebar a.active {
    background: var(--card2);
    color: #fff;
    box-shadow: inset 3px 0 0 var(--accent);
}
.content {
    margin-left: 300px;
    max-width: none;
    padding: 48px clamp(24px, 3vw, 56px) 96px;
}
.hero {
    background: linear-gradient(135deg, #0f2447 0%, #0b1a2c 60%, #07111e 100%);
    border: 1px solid var(--line);
    border-radius: 18px;
    padding: 40px 36px;
    margin-bottom: 32px;
    position: relative;
    overflow: hidden;
}
.hero::after {
    content: '';
    position: absolute;
    right: -80px;
    top: -80px;
    width: 260px;
    height: 260px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(124, 158, 255, 0.28), transparent 70%);
}
.eyebrow {
    display: inline-block;
    font-family: var(--mono);
    font-size: 12px;
    letter-spacing: 0.1em;
    color: var(--accent);
    border: 1px solid var(--accent);
    border-radius: 999px;
    padding: 3px 12px;
    margin-bottom: 16px;
}
.hero h1 {
    font-size: clamp(26px, 4vw, 38px);
    line-height: 1.35;
    margin: 0 0 14px;
    font-weight: 900;
    position: relative;
}
.hero-sub {
    font-size: 17px;
    color: #cfdcf5;
    margin: 0 0 10px;
    position: relative;
}
.hero-formal {
    font-size: 12px;
    color: var(--muted);
    margin: 0 0 18px;
    line-height: 1.6;
    font-family: var(--mono);
    word-break: break-word;
    position: relative;
}
.pills {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    position: relative;
}
.pill {
    background: rgba(124, 158, 255, 0.1);
    border: 1px solid var(--line);
    border-radius: 10px;
    padding: 6px 12px;
    font-size: 13px;
    line-height: 1.5;
}
.pk {
    color: var(--muted);
    margin-right: 8px;
}
.pv {
    color: #fff;
    font-weight: 500;
}
h2 {
    font-size: 26px;
    line-height: 1.4;
    margin: 64px 0 20px;
    padding: 14px 0 14px 18px;
    border-left: 5px solid var(--accent);
    background: linear-gradient(90deg, rgba(124, 158, 255, 0.12), transparent);
    border-radius: 0 10px 10px 0;
    font-weight: 700;
}
h3 {
    font-size: 20px;
    margin: 40px 0 14px;
    color: #fff;
    font-weight: 700;
    padding-bottom: 6px;
    border-bottom: 1px dashed var(--line);
}
p {
    margin: 0 0 16px;
}
ul,
ol {
    padding-left: 1.5em;
    margin: 0 0 18px;
}
li {
    margin: 4px 0;
}
strong {
    color: #fff;
    font-weight: 700;
}
.source-line {
    font-size: 13px;
    color: var(--muted);
    border-left: 3px solid var(--line);
    padding-left: 12px;
    margin: 18px 0;
}
.table-scroll {
    overflow-x: auto;
    margin: 18px 0 26px;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--card);
}
table {
    border-collapse: collapse;
    width: 100%;
    font-size: 14.5px;
    line-height: 1.65;
}
th {
    background: var(--card2);
    color: #fff;
    text-align: left;
    font-weight: 700;
    white-space: nowrap;
}
th,
td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--line);
    vertical-align: top;
}
tr:last-child td {
    border-bottom: none;
}
td {
    overflow-wrap: anywhere;
}
td:first-child {
    font-weight: 500;
}
tbody tr:hover {
    background: rgba(124, 158, 255, 0.06);
}
.callout-stack {
    margin: 22px 0;
}
.callout {
    border: 1px solid var(--line);
    border-left: 5px solid var(--accent);
    border-radius: 12px;
    background: var(--card);
    padding: 14px 18px;
    margin: 0 0 14px;
}
.callout-head {
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 700;
    margin-bottom: 6px;
}
.callout-body p {
    margin: 0 0 8px;
    font-size: 15px;
}
.callout-body p:last-child {
    margin-bottom: 0;
}
.callout-body ul {
    margin: 6px 0 0;
}
.callout-practice {
    border-left-color: var(--green);
    background: rgba(86, 214, 160, 0.07);
}
.callout-practice .callout-title {
    color: var(--green);
}
.callout-warn {
    border-left-color: var(--amber);
    background: rgba(226, 180, 90, 0.08);
}
.callout-warn .callout-title {
    color: var(--amber);
}
.callout-check {
    border-left-color: var(--violet);
    background: rgba(180, 156, 255, 0.08);
}
.callout-check .callout-title {
    color: var(--violet);
}
.diagram {
    margin: 22px 0 30px;
    background: #0a1626;
    border: 1px solid var(--line);
    border-radius: 14px;
    padding: 18px 10px 8px;
}
.diagram-scroll {
    overflow-x: auto;
    text-align: center;
}
.diagram svg {
    max-width: 100% !important;
    height: auto;
    display: inline-block;
    background: transparent;
}
.diagram foreignObject {
    overflow: visible;
}
.diagram foreignObject div,
.diagram foreignObject span,
.diagram foreignObject p {
    white-space: normal !important;
    margin: 0;
}
.diagram .edgeLabel,
.diagram .edgeLabel p,
.diagram .edgeLabel span {
    background-color: #0d1b2e !important;
    color: #dbe6ff !important;
}
.diagram .label,
.diagram .nodeLabel {
    line-height: 1.4;
}
.diagram figcaption {
    text-align: center;
    font-size: 12px;
    color: var(--muted);
    padding: 6px 0 4px;
    font-family: var(--mono);
}
.checklist {
    list-style: none;
    padding: 0;
    margin: 10px 0 8px;
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 12px;
    padding: 8px 16px;
}
.checklist li {
    padding: 8px 0;
    border-bottom: 1px solid var(--line);
    display: flex;
    gap: 12px;
    align-items: flex-start;
}
.checklist li:last-child {
    border-bottom: none;
}
.checklist input {
    margin-top: 7px;
    width: 18px;
    height: 18px;
    accent-color: var(--green);
    flex: none;
}
.progress {
    display: flex;
    align-items: center;
    gap: 14px;
    margin: 0 0 24px;
}
.progress-track {
    flex: 1;
    height: 10px;
    background: var(--card2);
    border-radius: 999px;
    overflow: hidden;
}
.progress-fill {
    height: 100%;
    width: 0;
    background: linear-gradient(90deg, var(--accent), var(--green));
    transition: width 0.3s;
}
.progress-label {
    font-size: 13px;
    color: var(--muted);
    font-family: var(--mono);
    white-space: nowrap;
}
.footer-note {
    margin-top: 64px;
    padding-top: 20px;
    border-top: 1px solid var(--line);
    color: var(--muted);
    font-size: 13px;
}
.nav-toggle,
.scrim {
    display: none;
}
@media (max-width: 980px) {
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.25s;
        width: min(86vw, 320px);
    }
    body.nav-open .sidebar {
        transform: none;
    }
    .nav-toggle {
        display: block;
        position: fixed;
        top: 12px;
        left: 12px;
        z-index: 40;
        background: var(--card2);
        color: #fff;
        border: 1px solid var(--line);
        border-radius: 10px;
        padding: 8px 14px;
        font: inherit;
        font-size: 14px;
    }
    body.nav-open .scrim {
        display: block;
        position: fixed;
        inset: 0;
        background: rgba(0, 0, 0, 0.55);
        z-index: 25;
    }
    .content {
        margin-left: 0;
        padding: 64px 16px 72px;
    }
    .hero {
        padding: 26px 20px;
    }
    h2 {
        font-size: 22px;
    }
}
@media print {
    .sidebar,
    .nav-toggle,
    .scrim {
        display: none;
    }
    .content {
        margin: 0;
    }
}

/* ===== 13 FAQ ===== */
.faq-toolbar {
    display: flex;
    align-items: center;
    gap: 10px;
    margin: 6px 0 14px;
}
.faq-count {
    margin-right: auto;
    font-family: var(--mono);
    font-size: 13px;
    color: var(--muted);
}
.btn-ghost {
    background: transparent;
    color: var(--accent);
    border: 1px solid var(--line);
    border-radius: 999px;
    padding: 6px 14px;
    font: inherit;
    font-size: 13px;
    cursor: pointer;
    transition: 0.15s;
}
.btn-ghost:hover {
    background: rgba(124, 158, 255, 0.12);
    border-color: var(--accent);
}
.faq-list {
    display: grid;
    gap: 12px;
    margin-bottom: 24px;
}
.faq-item {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 14px;
    overflow: hidden;
    transition:
        border-color 0.15s,
        box-shadow 0.15s;
}
.faq-item[open] {
    border-color: rgba(124, 158, 255, 0.55);
    box-shadow: 0 6px 24px rgba(0, 0, 0, 0.25);
}
.faq-item summary {
    list-style: none;
    cursor: pointer;
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 16px 18px;
    font-weight: 700;
    color: #fff;
    line-height: 1.6;
    position: relative;
    padding-right: 48px;
}
.faq-item summary::-webkit-details-marker {
    display: none;
}
.faq-item summary::after {
    content: '';
    position: absolute;
    right: 20px;
    top: 22px;
    width: 9px;
    height: 9px;
    border-right: 2px solid var(--muted);
    border-bottom: 2px solid var(--muted);
    transform: rotate(45deg);
    transition: transform 0.2s;
}
.faq-item[open] summary::after {
    transform: rotate(-135deg);
    top: 26px;
}
.faq-item summary:hover {
    background: rgba(124, 158, 255, 0.06);
}
.q-badge,
.a-badge {
    flex: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 38px;
    height: 28px;
    padding: 0 10px;
    border-radius: 8px;
    font-family: var(--mono);
    font-size: 13px;
    font-weight: 700;
}
.q-badge {
    background: rgba(124, 158, 255, 0.18);
    color: var(--accent);
    border: 1px solid rgba(124, 158, 255, 0.5);
}
.a-badge {
    background: rgba(86, 214, 160, 0.16);
    color: var(--green);
    border: 1px solid rgba(86, 214, 160, 0.5);
    min-width: 28px;
    padding: 0;
}
.faq-answer {
    display: flex;
    gap: 14px;
    padding: 4px 18px 18px;
    border-top: 1px dashed var(--line);
    padding-top: 16px;
    background: linear-gradient(180deg, rgba(86, 214, 160, 0.05), transparent);
}
.a-body {
    flex: 1;
    min-width: 0;
}
.a-body p {
    margin: 0;
    font-size: 15px;
    line-height: 1.9;
}

/* ===== 14 Glossary ===== */
.gloss-toolbar {
    display: flex;
    align-items: center;
    gap: 14px;
    margin: 6px 0 16px;
}
.gloss-search {
    flex: 1;
    max-width: 480px;
    background: var(--card);
    color: var(--text);
    border: 1px solid var(--line);
    border-radius: 999px;
    padding: 10px 18px;
    font: inherit;
    font-size: 14px;
    outline: none;
}
.gloss-search:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(124, 158, 255, 0.2);
}
.gloss-count {
    font-family: var(--mono);
    font-size: 13px;
    color: var(--muted);
}
.gloss-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 14px;
    margin-bottom: 18px;
}
.gloss-card {
    background: var(--card);
    border: 1px solid var(--line);
    border-top: 3px solid var(--accent);
    border-radius: 12px;
    padding: 14px 16px;
    transition:
        transform 0.15s,
        border-color 0.15s;
}
.gloss-card:hover {
    transform: translateY(-2px);
    border-color: var(--accent);
}
.gloss-card:nth-child(3n + 2) {
    border-top-color: var(--green);
}
.gloss-card:nth-child(3n) {
    border-top-color: var(--violet);
}
.gloss-term {
    font-weight: 700;
    color: #fff;
    font-size: 16px;
    margin-bottom: 6px;
}
.gloss-def {
    font-size: 14px;
    color: #cdd9ee;
    line-height: 1.75;
}
.gloss-card[hidden] {
    display: none;
}
.gloss-empty {
    display: none;
    color: var(--muted);
    text-align: center;
    padding: 20px;
}

/* ===== 15 Self check ===== */
.check-card {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 16px;
    padding: 6px 20px 16px;
    margin: 10px 0 28px;
}
.check-head {
    display: flex;
    align-items: baseline;
    gap: 12px;
    padding: 14px 0 10px;
    border-bottom: 1px solid var(--line);
    flex-wrap: wrap;
}
.check-title {
    font-weight: 700;
    color: #fff;
    font-size: 17px;
}
.check-hint {
    font-size: 13px;
    color: var(--muted);
}
.check-card .checklist {
    background: transparent;
    border: none;
    border-radius: 0;
    padding: 0;
    margin: 0;
}
.check-card .checklist li {
    display: block;
    padding: 0;
    border-bottom: 1px solid var(--line);
}
.check-card .checklist li:last-child {
    border-bottom: none;
}
.check-card .checklist label {
    display: flex;
    gap: 14px;
    align-items: center;
    padding: 13px 6px;
    cursor: pointer;
    border-radius: 8px;
    transition: background 0.15s;
}
.check-card .checklist label:hover {
    background: rgba(124, 158, 255, 0.07);
}
.check-card .checklist input {
    appearance: none;
    -webkit-appearance: none;
    flex: none;
    width: 24px;
    height: 24px;
    margin: 0;
    border: 2px solid #4b6694;
    border-radius: 7px;
    background: transparent;
    display: grid;
    place-content: center;
    cursor: pointer;
    transition: 0.15s;
}
.check-card .checklist input::before {
    content: '';
    width: 12px;
    height: 6px;
    border-left: 3px solid #07111e;
    border-bottom: 3px solid #07111e;
    transform: rotate(-45deg) scale(0);
    margin-top: -3px;
    transition: transform 0.15s;
}
.check-card .checklist input:checked {
    background: var(--green);
    border-color: var(--green);
}
.check-card .checklist input:checked::before {
    transform: rotate(-45deg) scale(1);
}
.check-card .checklist input:focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
}
.check-card .checklist li.done label {
    color: var(--muted);
}
.check-card .checklist li.done label span,
.check-card .checklist li.done label {
    text-decoration: line-through;
    text-decoration-color: rgba(157, 176, 204, 0.5);
}
.check-card .progress {
    margin: 14px 0 0;
}
.check-card .progress.complete .progress-label {
    color: var(--green);
    font-weight: 700;
}
.quiz-card {
    background: var(--card);
    border: 1px solid var(--line);
    border-left: 5px solid var(--violet);
    border-radius: 14px;
    margin: 0 0 14px;
    overflow: hidden;
}
.quiz-card summary {
    list-style: none;
    cursor: pointer;
    display: flex;
    gap: 14px;
    align-items: flex-start;
    padding: 16px 18px;
    color: #fff;
    font-weight: 500;
    line-height: 1.7;
}
.quiz-card summary::-webkit-details-marker {
    display: none;
}
.quiz-card summary:hover {
    background: rgba(180, 156, 255, 0.07);
}
.qz-badge {
    flex: none;
    background: rgba(180, 156, 255, 0.18);
    color: var(--violet);
    border: 1px solid rgba(180, 156, 255, 0.5);
    border-radius: 8px;
    padding: 2px 12px;
    font-weight: 700;
    font-size: 14px;
    line-height: 1.7;
}
.qz-text {
    flex: 1;
}
.qz-hint {
    flex: none;
    font-size: 12px;
    color: var(--accent);
    border: 1px solid var(--line);
    border-radius: 999px;
    padding: 3px 12px;
    white-space: nowrap;
}
.quiz-card[open] .qz-hint {
    display: none;
}
.qz-answer {
    display: flex;
    gap: 14px;
    padding: 14px 18px 18px;
    border-top: 1px dashed var(--line);
    background: rgba(86, 214, 160, 0.06);
}
.qz-a-badge {
    flex: none;
    background: rgba(86, 214, 160, 0.16);
    color: var(--green);
    border: 1px solid rgba(86, 214, 160, 0.5);
    border-radius: 8px;
    padding: 2px 12px;
    font-weight: 700;
    font-size: 14px;
    line-height: 1.7;
    height: fit-content;
}
.qz-a-body {
    flex: 1;
    min-width: 0;
    font-size: 15px;
}
@media (max-width: 640px) {
    .gloss-grid {
        grid-template-columns: 1fr;
    }
    .qz-hint {
        display: none;
    }
    .faq-answer,
    .qz-answer {
        gap: 10px;
    }
}
.check-card .checklist li {
    margin: 0;
}
.check-card .checklist label {
    padding: 10px 6px;
}
